import com.mushafi.app.DailyReminderPlan;import java.util.*;
public class DailyReminderPlanTest {
 static void check(boolean value){if(!value)throw new AssertionError();}
 static long time(String value,TimeZone zone)throws Exception{java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.US);f.setTimeZone(zone);return f.parse(value).getTime();}
 public static void main(String[] args)throws Exception{for(String name:new String[]{"Asia/Riyadh","America/New_York","Europe/London","Asia/Tokyo"}){TimeZone z=TimeZone.getTimeZone(name);long base=time("2026-10-30 07:29",z);check(!DailyReminderPlan.fridayWindow(base,z));check(DailyReminderPlan.fridayWindow(time("2026-10-30 07:30",z),z));check(DailyReminderPlan.fridayWindow(time("2026-10-30 11:59",z),z));check(!DailyReminderPlan.fridayWindow(time("2026-10-30 12:00",z),z));check(!DailyReminderPlan.fridayWindow(time("2026-10-31 09:00",z),z));Set<String> ids=new HashSet<>();for(DailyReminderPlan.Event e:DailyReminderPlan.fixed(base,z)){check(ids.add(e.id));Calendar c=DailyReminderPlan.day(e.at,z,0);int h=c.get(Calendar.HOUR_OF_DAY),m=c.get(Calendar.MINUTE);if(e.kind.equals("morning"))check(h==5&&m==0);if(e.kind.equals("evening"))check(h==17&&m==0);if(e.kind.equals("night"))check(h==22&&m==30);if(e.kind.equals("salawat"))check(c.get(Calendar.DAY_OF_WEEK)==Calendar.FRIDAY&&h==9&&m==0);}
 long before=DailyReminderPlan.slot(time("2026-10-30 07:59",z),z);check(DailyReminderPlan.slot(time("2026-10-30 08:00",z),z)==before+1);check(DailyReminderPlan.slot(time("2026-10-30 19:59",z),z)==before+1);check(DailyReminderPlan.slot(time("2026-10-30 20:00",z),z)==before+2);Set<Integer> pool=new HashSet<>();for(int d=0;d<11;d++)for(int hour:new int[]{8,20}){Calendar c=DailyReminderPlan.day(base,z,d);pool.add(DailyReminderPlan.duaIndex(DailyReminderPlan.wall(c,hour,0),z,22));}check(pool.size()==22);}
 for(int i=1;i<=12;i++)check(DailyReminderPlan.showVisit(i)==(i==1||i==4||i==7||i==10));TimeZone ny=TimeZone.getTimeZone("America/New_York");for(String date:new String[]{"2026-03-07 12:00","2026-10-31 12:00"}){Set<String> unique=new HashSet<>();for(DailyReminderPlan.Event e:DailyReminderPlan.fixed(time(date,ny),ny))check(unique.add(e.id));}System.out.println("PASS: 4 zones, Friday 07:30 inclusive / noon exclusive, visits 1/4/7/10, fixed times, all 22 half-day picks, DST unique event IDs.");}
}
